// Direct-entry flight lobby. Existing mode actions remain authoritative.
const lobbyLabels={ko:['ストーリー','무한','창작','기록','상점','배지','설정','장착 중','항로를 선택해 출발하세요'],en:['Story','Endless','Create','Records','Shop','Badges','Settings','Equipped','Choose your next flight'],ja:['ストーリー','無限','創作','記録','ショップ','バッジ','設定','装備中','次の航路を選んでください'],zh:['故事','无限','创作','纪录','商店','徽章','设置','已装备','选择下一条航线']};lobbyLabels.ko[0]='스토리';
const lobbyIcons={story:'M8 6h7v20H8z M19 6h7v20h-7z M15 12h4m-4 8h4',endless:'M16 16c-11-18-22 13-7 8 8-3 6-15 15-16 15-2 5 29-8 8',creator:'M7 8h18v18H7z M12 17h8m-4-4v8 M21 3v8m-4-4h8',records:'M9 26V16h4v10m4 0V7h4v19 M5 28h22',shop:'M5 12h22l-3-7H8z M7 12v15h18V12 M13 27v-9h6v9',badges:'M16 4 26 8v10c0 6-10 11-10 11S6 24 6 18V8z M16 10l2 5 5 1-4 3 1 5-4-3-4 3 1-5-4-3 5-1z',settings:'M11 5h10l1 5 5 1v10l-5 1-1 5H11l-1-5-5-1V11l5-1z M21 16a5 5 0 1 0-10 0 5 5 0 0 0 10 0'};
function lobbyIcon(key){return '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="'+lobbyIcons[key]+'" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
function updateLobby(){const w=lobbyLabels[settings.language]||lobbyLabels.ko;['story','endless','creator','records','shop','badges','settings'].forEach((key,i)=>{$('lobby-'+key).innerHTML=lobbyIcon(key)+'<span>'+w[i]+'</span>'});$('lobbyShipLabel').textContent=w[7];$('lobbyShipName').textContent=tr(skins[data.skin][0]);$('lobbyHint').textContent=w[8];$('lobbyWallet').textContent='◈ '+data.coins.toLocaleString();$('lobbyProgress').textContent=data.cleared.filter(i=>i>=0&&i<STORY_VISIBLE_COUNT).length+' / '+STORY_VISIBLE_COUNT;$('lobbyBack').textContent='‹ '+({ko:'메인',en:'Home',ja:'ホーム',zh:'主页'}[settings.language]||'Home');}
for(const [key,target]of [['story','story'],['endless','endless'],['records','records'],['shop','shop'],['badges','badges'],['settings','options']])$('lobby-'+key).onclick=()=>showMenu(target);
$('lobby-creator').onclick=()=>openCreator();$('lobbyBack').onclick=()=>showMenu('main');
const lobbyMenu=showMenu;showMenu=function(tab='main'){if(tab==='modes')tab='main';const out=lobbyMenu(tab);if(menuScreen==='records'){$('shopgrid').style.gridTemplateRows='none';$('shopgrid').scrollTop=0;}updateLobby();$('overlay').setAttribute('data-lobby',String(menuScreen==='main'&&state==='menu'));if(menuScreen==='main')paintLobbyShip();return out};
const lobbyHome=$('home').onclick;$('home').onclick=()=>{if(['story','endless','records','shop','badges','options','creator'].includes(menuScreen)&&state==='menu')return showMenu('main');return lobbyHome()};
let lobbyClock=0,lobbyPreviousFrame=null,shopClock=0,shopPreviousFrame=null;
function lobbyShipPose(seconds,reduced=false,id=data.skin){const cycle=seconds%5,u=(cycle-1.2)/1.35,air=!reduced&&u>0&&u<1,trick=air?trickTransform(id,u):{yaw:0,roll:0,flip:0,pulse:0},landing=!reduced&&cycle>=2.55&&cycle<2.85?landingPoseAt((cycle-2.55)/.3,.85):{sink:0,pitch:0,boost:0};return {lift:(air?Math.sin(Math.PI*u)*66:0)-landing.sink,yaw:(reduced?-.35:-seconds*.42)+trick.yaw,roll:trick.roll,flip:trick.flip+landing.pitch,thrust:(air?.65:.12)+landing.boost+((id===2||id===4)?trick.pulse*.4:0),jumpTrick:air?u:null};}
function paintLobbyShip(){const c=$('lobbyShip');if(!c.width)c.width=600;if(!c.height)c.height=480;const g=c.getContext('2d'),seconds=lobbyClock,reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches,p=lobbyShipPose(seconds,reduced);g.clearRect(0,0,c.width,c.height);g.save();g.translate(c.width/2,c.height*.56);g.fillStyle='#00000045';g.beginPath();g.ellipse(0,84,104-p.lift*.25,22-p.lift*.05,0,0,Math.PI*2);g.fill();g.translate(0,-p.lift);renderSolidJumpShip(g,data.skin,seconds,112,{foreshortening:.65,shear:0,thrust:p.thrust},{yaw:p.yaw,roll:p.roll,flip:p.flip});g.restore();}
// Ship-only animation follows requestAnimationFrame; the background stays on its idle budget.
function lobbyAnimationFrame(timestamp){const visible=menuScreen==='main'&&state==='menu'&&!document.hidden&&!globalThis.flightLifecycleSuspended;if(visible){if(lobbyPreviousFrame!==null)lobbyClock+=Math.max(0,Math.min((timestamp-lobbyPreviousFrame)/1000,.05));paintLobbyShip();lobbyPreviousFrame=timestamp}else lobbyPreviousFrame=null;const shopVisible=menuScreen==='shop'&&state==='menu'&&cosmeticTab!=='coins'&&!document.hidden&&!globalThis.flightLifecycleSuspended;if(shopVisible){if(shopPreviousFrame!==null)shopClock+=Math.max(0,Math.min((timestamp-shopPreviousFrame)/1000,.05));paintTrickShopPreview(shopClock);shopPreviousFrame=timestamp}else shopPreviousFrame=null;requestAnimationFrame(lobbyAnimationFrame)}
requestAnimationFrame(lobbyAnimationFrame);
showMenu('main');
